use glam::{Vec2,Vec3};
use crate::{Sim,SimEvent};
use super::{*,data::{distance,flat}};
impl Merc{
 pub fn current_goal(&self)->Option<data::GoalDef>{if self.contract>=self.data.contracts.len(){return None;}self.data.contracts[self.contract].goal.get(self.goal).cloned()}
 pub fn goal_pos(&self)->Vec3{self.current_goal().map(|g|self.data.place(&g.place).pos()).unwrap_or(self.pos)}
 pub fn accept_contract(&mut self){self.contract_active=true;self.goal=0;self.goal_time=0.;self.goal_flag=false;self.save_serial+=1;let c=self.data.contracts[self.contract].clone();self.say(&c.giver,c.brief.replace('\n'," "));self.open("playing");if self.contract==3{self.owned.insert(9);self.guns[1]=Gun::new(9,&self.data.weapons[9],100.);}if self.contract==6{self.owned.insert(8);self.guns[1]=Gun::new(8,&self.data.weapons[8],100.);}if self.contract==7{self.owned.insert(12);self.guns[2]=Gun::new(12,&self.data.weapons[12],100.);}if self.contract==5{self.better_way=true;self.flag("better_way_taken");}}
 pub fn contract_tick(&mut self,sim:&mut Sim,dt:f32,events:&mut Vec<SimEvent>){if self.session {self.round_time+=dt;let destroyed=self.objects.iter().filter(|o|o.place=="depot"&&o.kind==1&&o.exploded).count();if destroyed==3&&self.ledger_carrier>=0 {let exit=self.data.place("depot").pos()+Vec3::new(0.,0.,500.);let me=self.local_id==255||self.health<=0.||distance(self.pos,exit)<30.;let peers=self.peers.iter().filter(|p|p.present&&p.hp>0.).all(|p|distance(p.pos,exit)<30.);if me&&peers{self.finished=true;self.won=true;self.team_score+=100;}}if self.round_time>600.{self.finished=true;self.won=false;}return;}
 if self.ending>0 {self.ending_time+=dt;if self.ending==2{if (self.ending_time/12.).floor() as i32!=((self.ending_time-dt)/12.).floor() as i32 {let p=self.pos+Vec3::new(24.,0.,-24.);self.spawn_enemy(sim,p,(self.ending_time as u8/12)%5);self.fire.ignite(&self.data,flat(p),3.);}if self.ending_time>=180.{self.end_interview();}}else if self.ending_time>14.{self.end_interview();}return;}
 if !self.contract_active{return;}let Some(goal)=self.current_goal() else{return;};let p=self.data.place(&goal.place).pos();let near=distance(self.pos,p)<if goal.kind=="target"{450.}else{30.};self.goal_time+=dt;
 let success=match goal.kind.as_str(){"reach"=>near,"pills"=>self.coverage.contains("pill_taken"),"clear"=>self.posts.iter().any(|q|q.place==goal.place&&q.cleared),"claim"=>self.posts.iter().any(|q|q.place==goal.place&&q.claimed),"shop"=>self.coverage.contains("weapon_bought"),"tanks"=>self.objects.iter().filter(|o|o.place==goal.place&&o.kind==1&&o.exploded).count()>=3,"escape"=>near,"night"=>self.coverage.contains("sleep_used")&&!(5.0..20.0).contains(&self.hour),"tag"=>self.soldiers.iter().any(|n|n.target&&(n.tagged||n.hp<=0.)),"target"=>self.soldiers.iter().any(|n|n.target&&n.hp<=0.),"companion"=>self.goal_flag||self.companions.iter().any(|c|!c.alive),_=>self.goal_flag};
 if self.contract==0&&self.goal==1&&near&&self.fever_state==0&&!self.coverage.contains("pill_taken"){self.fever_timer=35.;self.note("The bar door is close. So is the fever.");}
 if success{self.advance_goal(sim,events);}
 }
 pub fn advance_goal(&mut self,_sim:&mut Sim,_events:&mut Vec<SimEvent>){self.goal+=1;self.goal_time=0.;self.goal_flag=false;let c=self.data.contracts[self.contract].clone();if self.goal>=c.goal.len(){self.complete.insert(self.contract);self.flag(&format!("contract_{}",c.id));let pay=(c.pay as f32*self.tuning.contract_pay).round() as i32;self.diamonds+=pay;if matches!(self.contract,2|6){self.income[0]+=pay;}else{self.income[1]+=pay;}self.infamy+=1;self.contract_active=false;self.save_serial+=1;self.note(format!("{} · +{} diamonds. {}",c.name,pay,self.s("mission_end")));if self.contract==0{self.pills=3;self.health=100.;self.collect_tape("bar");}if self.contract==1{for c in &mut self.companions{c.recruited=c.alive;}}if self.contract==4{self.pills=5;}if self.contract==6{self.ceasefire=false;self.flag("ceasefire_ended");self.say("Thandiwe Moyo",self.s("ceasefire").to_string());}if self.contract==8{self.town_burned=true;self.flag("town_burned");}if self.contract<10{self.contract+=1;}if self.contract==8{self.hour=22.;let p=self.data.place("town").pos();self.fire.ignite(&self.data,flat(p)+Vec2::new(35.,25.),8.);}if self.contract==10{self.open("ending_choice");}else{self.parent="playing".into();self.open("contract");}}}
 pub fn interact_goal(&mut self,sim:&mut Sim,events:&mut Vec<SimEvent>)->bool{if self.session {let depot=self.data.place("depot").pos();if distance(self.pos,depot)<25.&&self.objects.iter().filter(|o|o.place=="depot"&&o.exploded).count()>=3{if self.ledger_carrier<0{self.ledger_carrier=self.local_id as i32;self.team_score+=100;self.note("Ledger taken. Reach the extraction boat, 500 m south.");}else if self.ledger_carrier==self.local_id as i32{self.ledger_carrier=-1;}return true;}return false;}
 if !self.contract_active{return false;}let Some(goal)=self.current_goal()else{return false;};let p=self.data.place(&goal.place).pos();if distance(self.pos,p)>30.{return false;}match goal.kind.as_str(){"sabotage"=>{self.goal_flag=true;self.flag("night_contract");self.collect_tape("mission");self.fire.ignite(&self.data,flat(p)+Vec2::new(7.,0.),2.);self.note("Pump governor removed. Water has changed owners.");},"cargo"=>{self.goal_flag=true;let v=self.vehicles.iter().position(|v|v.kind==2).unwrap_or(0);self.vehicles[v].pos=self.pos+Vec3::new(4.,0.,0.);self.vehicles[v].hp=100.;self.note("Medicine loaded. Truck keys on the dash.");},"deliver"=>{if !self.coverage.contains("repair_done"){if let Some(i)=self.riding{self.vehicles[i].hp=28.;self.riding=None;}self.note("The engine has stopped. Repair it at the hood.");return true;}self.goal_flag=true;self.pills=5;self.collect_tape("mission");},"convoy"=>{let enemies=self.soldiers.iter().any(|n|n.hp>0.&&distance(n.pos,p)<35.);if enemies{self.note("The manifest is under armed supervision.");return true;}self.goal_flag=true;if self.contract==5{if let Some(c)=self.companions.iter_mut().find(|c|c.alive&&c.recruited){c.pos=self.pos+Vec3::new(8.,0.,4.);c.down=self.tuning.rescue_window;c.mortal=self.trouble_count%2==1;self.trouble_count+=1;}self.say("Companion",self.s("companion_down").to_string());}},"manifest"=>{self.goal_flag=true;self.collect_tape("works");self.note("The same stencils. The same signature.");},"evacuate"=>{self.open("evacuate");},"ledger"=>{self.goal_flag=true;self.collect_tape("works");self.say("The Chandler",self.s("ledger").to_string());},_=>return false};let _=(sim,events);true}
 pub fn choose_ending(&mut self,n:u8){self.ending=n;self.ending_time=0.;self.flag(match n{1=>"ending_burn",2=>"ending_read",_=>"ending_chair"});self.contract_active=false;if n==1{self.fire.ignite(&self.data,flat(self.data.place("works").pos()),12.);self.say("Field note",self.s("ending_burn").to_string());}else if n==2{self.say("Thandiwe Moyo",self.s("ending_read").to_string());}else{self.say("Radio",self.s("ending_chair").to_string());}self.open(if n==2{"ending_defend"}else{"playing"});}
 pub fn end_interview(&mut self){self.outcome=Outcome::Won;self.complete.insert(10);self.flag("contract_D2");let merc=self.s(&format!("dossier_{}",self.merc)).split('|').next().unwrap_or("").to_string();let lost=self.companions.iter().filter(|c|!c.alive).count();let paid=if self.income[0]>self.income[1]{"the Council"}else{"the Hand"};self.say("Your voice",format!("{merc}. {lost} companions lost. Most of the money came from {paid}. Moyo: Would you do it again? You leave the tape running."));self.open("ending");self.save_serial+=1;}
 pub fn spawn_enemy(&mut self,_sim:&mut Sim,mut p:Vec3,role:u8){p.y=terrain::height(&self.data,p.x,p.z);self.soldiers.push(Soldier{pos:p,home:p,yaw:0.,hp:80.,role,faction:role%2,group:18,detection:1.,state:2,timer:20.,cooldown:2.,gun:Gun::new(4,&self.data.weapons[4],35.),entity:None,tagged:false,poison:0.,burning:0.,target:false});}
}
